package calc

import "math"

// 0x502d00 game_turns_passed(ticks): the per-tick upkeep. Fixture world and
// stubs: re/emu/cases/00502d00.json; the 0x551500 sweep and 0x4e6020 release
// are the spcWorld helpers of n_4fb4c0.go.
//
// Emu address-stubs the D4 callees 0x503100 (character upkeep), 0x503990
// (monster upkeep), 0x5526f0 / 0x552ef0 (party spell and aura upkeep),
// 0x50e700 (party effect rebuild), 0x4e4ab0 and 0x50ca80; their returns are
// unread here and are case inputs. F runs their Go functions through marCall
// (gtpCallees), so what they write reaches the rest of this node. 0x552410
// (in the sweep) is monsterMentalResistRollNode in F. 排除 callees (0x58aad0
// log, 0x408860 sound, 0x562a50 refresh, 0x4263f0 / 0x422d50 screen, 0x46e440 /
// 0x42ef00 / 0x434b60 area query, 0x4537e0) are address stubs.
//
// Fixture caps (calc panics past them): monster list count <= 3, timer
// instance count 0x689b5c <= 3, NPC record count [0x689f94]+4 <= 3, 0x42ef00
// hit count <= 6 (sweep). Every other input covers its full width; ticks is a
// full u32 (the 0x500e90 per-tick loop is computed in one step).
const (
	gtpMonCap  = 3
	gtpInstCap = 3
	gtpNpcCap  = 3
	gtpTimeOut = 0xa8c0 // 0x50c82b: clock span after which an NPC flag lapses
)

func gtpPanic(s string) { panic("game turns passed: " + s) }

// gtpZero is an x87 fcomp against 0.0 (0x5ebb34) taken as "equal": C3 is set
// for equal and for unordered operands.
func gtpZero(x float64) bool { return x == 0 || math.IsNaN(x) }

func gtpF32(s *spcWorld, a uint32) float64 { return float64(math.Float32frombits(s.u32(a))) }

func gtpStub(s *spcWorld, a uint32, args ...uint32) uint32 {
	k := s.call(a, args...)
	if c := gtpCallees[a]; s.real && c != nil {
		return marCall(s.mcaWorld, c, args)
	}
	return s.replay(a, k, args...)
}

func gtpMonsters(s *spcWorld) uint32 {
	n := s.listCount(s.u32(0x683fad)) // 0x5e2c70
	if n > gtpMonCap {
		gtpPanic("monster list past the fixture's 3 records")
	}
	return n
}

func gtpInsts(s *spcWorld) int32 {
	n := int32(s.u32(0x689b5c))
	if n > gtpInstCap {
		gtpPanic("timer instance count past the fixture's 3 records")
	}
	return n
}

// gtpExpire is one effect slot (flag +0, id +1, +5, duration +0xd); true when
// it ran out this call.
func gtpExpire(s *spcWorld, e, ticks uint32) bool {
	if s.u8(e) == 0 {
		return false
	}
	if d := s.u32(e + 0xd); d > ticks {
		s.put32(e+0xd, d-ticks)
		return false
	}
	// 0x58aad0 log line: text 0x6d0/4 of [0x68c09c], spell record name (0x1bf
	// bytes per record at [0x65be1c], name at +0x9b).
	gtpStub(s, 0x58aad0, 0xc, s.u32(s.u32(0x68c09c)+0x6d0), s.u32(e+1)*0x1bf+s.u32(0x65be1c)+0x9b)
	if v := gtpF32(s, 0x60a390); !(v == 2880 || math.IsNaN(v)) { // 0x482760 vs 0x5ec918 (2880.0)
		gtpStub(s, 0x408860, 0x619898, 0)
	}
	gtpClear(s, e)
	return true
}

// gtpClear is 0x5524b0(e).
func gtpClear(s *spcWorld, e uint32) {
	s.put8(e, 0)
	s.put32(e+1, 0)
	s.put32(e+5, 0)
	s.put32(e+0xd, 0)
	gtpStub(s, 0x50e700)
	if s.u32(0x68ec78) == 7 { // 0x5af2d0: screen rect clear + dirty mark
		gtpStub(s, 0x4263f0, 0x7f, 0x14, 0x201, 0x28)
		gtpStub(s, 0x422d50, 0x7f, 0x14, 0x201, 0x28, 0)
	}
	gtpStub(s, 0x562a50, 0x800100)
}

// gtpTimers is ticks calls of 0x500e90: each call counts every instance's
// timer (+4) down by one; an instance of type 0x26 that reaches 0 releases
// every listed monster not in actor state 0x15 (0x4e6020 mode 0).
func gtpTimers(s *spcWorld, ticks uint32) {
	if ticks == 0 {
		return
	}
	n, data := gtpInsts(s), s.u32(0x689b64)
	for i := int32(0); i < n; i++ {
		inst := s.u32(data + 4*uint32(i))
		d := s.u32(inst + 4)
		if d == 0 {
			continue
		}
		if d > ticks {
			s.put32(inst+4, d-ticks)
			continue
		}
		s.put32(inst+4, 0)
		if s.u32(inst) != 0x26 {
			continue
		}
		// The release passes only read monster state, so their order among
		// instances (by countdown, then index) does not change the result.
		for j := uint32(0); j < gtpMonsters(s); j++ {
			if m := s.listAt(s.u32(0x683fad), j); m != 0 && !s.act15(s.u32(m+0xc)) {
				s.release(m, 0)
			}
		}
	}
}

// gtpFirst is 0x500f30: the first instance of type 0x26.
func gtpFirst(s *spcWorld) uint32 {
	n, data := gtpInsts(s), s.u32(0x689b64)
	for i := int32(0); i < n; i++ {
		if inst := s.u32(data + 4*uint32(i)); s.u32(inst) == 0x26 {
			return inst
		}
	}
	return 0
}

// gtpNpcs is 0x50c7d0(t) over the records of [0x689f94].
func gtpNpcs(s *spcWorld, t uint32) {
	tab := s.u32(0x689f94)
	if tab == 0 {
		gtpPanic("no NPC table (0x50c7d7 dereferences it)")
	}
	for i := uint32(0); i < s.u32(tab+4); i++ {
		if i >= gtpNpcCap {
			gtpPanic("NPC records past the fixture's 3")
		}
		r := s.u32(s.u32(tab+0xc) + 4*i)
		if s.u8(r+0xc7) != 0 {
			continue
		}
		if s.u8(r+0x1c) != 0 {
			v := s.u32(r+0x1e) + t
			s.put32(r+0x1e, v)
			if v > 0x3c {
				s.put8(r+0x1c, 0)
			}
		}
		for _, f := range [2][2]uint32{{0xc8, 0xcc}, {0xc9, 0xd0}} {
			if s.u8(r+f[0]) != 0 && s.u32(0x686a48)-s.u32(r+f[1]) > gtpTimeOut {
				s.put8(r+f[0], 0)
			}
		}
	}
}

func gtpBody(w *mcaWorld) {
	w.tab = gtpStubs
	s := &spcWorld{mcaWorld: w}
	ticks := s.arg(0)
	if gtpZero(gtpF32(s, 0x687505) + gtpF32(s, 0x687501)) {
		switch s.u32(0x687509) {
		case 0, 1:
			s.put32(0x687509, 2)
			for k := uint32(0); k < 8; k++ {
				s.put32(s.u32(0x685178)+k*0x106+0xf6, 0)
			}
		case 2:
			s.put32(0x687509, 3)
		}
	} else {
		st := uint32(1)
		if gtpZero(gtpF32(s, 0x687505)) {
			st = 0
		}
		s.put32(0x687509, st)
		s.put32(0x687501, 0)
		s.put32(0x687505, 0)
	}
	for i := uint32(0); i < 8; i++ {
		if s.u8(s.u32(0x685178)+i*0x106) == 0 {
			continue
		}
		c := s.charBase(i)
		// 0x5248a0(i, 1): byte +0x181f + 0x11*1
		if s.u32(c+0xb01) < 0x12 || s.u32(c+0xa49) == 0 && s.u8(c+0x1830) != 0 {
			gtpStub(s, 0x503100, i, ticks)
		}
	}
	if s.u8(0x683f94) != 0 {
		t := s.local(32) // 0x536170: zeroed, +4 / +8 / +0xc = -1; then +0 = 2
		for o := uint32(0); o < 32; o += 4 {
			s.put32(t+o, 0)
		}
		s.put32(t+4, 0xffffffff)
		s.put32(t+8, 0xffffffff)
		s.put32(t+0xc, 0xffffffff)
		s.put32(t, 2)
		gtpStub(s, 0x5526f0, s.u32(0x6836a8)+0x7c1, t)
		gtpStub(s, 0x552ef0, s.u32(0x6836a8)+0x85a)
	}
	for i := uint32(0); i < gtpMonsters(s); i++ {
		if m := s.monsterRecord(i); s.u32(m+0x107) < 0x12 {
			gtpStub(s, 0x503990, m, ticks, 0)
		}
	}
	var party, group bool
	for k := uint32(0); k < 12; k++ {
		party = gtpExpire(s, 0x68691f+0x11*k, ticks) || party
	}
	if s.u8(0x683f94) != 0 {
		for k := uint32(0); k < 9; k++ {
			group = gtpExpire(s, s.u32(0x6836a8)+0x7c1+0x11*k, ticks) || group
		}
		for k := uint32(0); k < 6; k++ {
			group = gtpExpire(s, s.u32(0x6836a8)+0x85a+0x11*k, ticks) || group
		}
	}
	if party {
		gtpStub(s, 0x562a50, 0x100)
	}
	if group {
		gtpStub(s, 0x562a50, 0x8000)
	}
	gtpTimers(s, ticks)
	if inst := gtpFirst(s); inst != 0 && s.u32(inst+4) != 0 {
		s.sweep(inst)
	}
	if party || group {
		gtpStub(s, 0x408860, 0x61935c, 0)
	}
	if s.u8(0x683fc5) == 0 {
		gtpStub(s, 0x4e4ab0)
	}
	gtpNpcs(s, ticks*10)
	gtpStub(s, 0x50ca80)
}

func gameTurnsPassedNode(in []int64, r Rand) []int64 { return mcaRun(&gtpSpec, true, gtpBody)(in, r) }

func gtpEmu(in []int64, r Rand) []int64 { return mcaRun(&gtpSpec, false, gtpBody)(in, r) }

func init() {
	Nodes["00502d00"] = Node{Addr: "00502d00", In: gtpIn, Out: gtpOut, F: gameTurnsPassedNode, Emu: gtpEmu}
}

